            .AddMetadataReference(projectId, MetadataReference.CreateFromFile(typeof(object).Assembly.Location))
            .AddAnalyzerReference(projectId, new GeneratorReference(new ReproGenerator().AsSourceGenerator()))
            .AddDocument(documentId, "App.cs", SourceText.From("class App {}"), filePath: @"C:\repro\App.cs")
            .AddAdditionalDocument(additionalId, "MainPage.xaml", SourceText.From("{initial}"), filePath: @"C:\repro\MainPage.xaml");

        var baseline = solution.GetProject(projectId)!;
        var broken = solution.WithAdditionalDocumentText(additionalId, SourceText.From("{broken")).GetProject(projectId)!;
        var repaired = broken.Solution.WithAdditionalDocumentText(additionalId, SourceText.From("{repaired}")).GetProject(projectId)!;
