        await AssertDiffDiagnosticsAsync("broken -> repaired", broken, repaired, 1);
        await AssertDiffDiagnosticsAsync("baseline -> repaired", baseline, repaired, 0);
        await AssertDiffDiagnosticsAsync("broken -> another", broken, another, 1);
