    private static async Task AssertGeneratorDiagnosticsAsync(string label, Project project, int expected)
    {
        var method = typeof(Project).GetMethod("GetSourceGeneratorDiagnosticsAsync", BindingFlags.Instance | BindingFlags.NonPublic)
            ?? throw new MissingMethodException("Project.GetSourceGeneratorDiagnosticsAsync");
        var diagnostics = await (ValueTask<ImmutableArray<Diagnostic>>)method.Invoke(project, new object[] { CancellationToken.None })!;
        Console.WriteLine($"Generator {label}: {diagnostics.Length} diagnostic(s)");
        if (diagnostics.Length != expected)
            throw new InvalidOperationException($"Generator {label}: expected {expected}, got {diagnostics.Length}");
