    private static async Task AssertDiffDiagnosticsAsync(string label, Project oldProject, Project newProject, int expected)
    {
        var features = Assembly.Load("Microsoft.CodeAnalysis.Features");
        var editSession = features.GetType("Microsoft.CodeAnalysis.EditAndContinue.EditSession", throwOnError: true)!;
        var method = editSession.GetMethod("GetProjectDifferencesAsync", BindingFlags.Static | BindingFlags.NonPublic)
            ?? throw new MissingMethodException("EditSession.GetProjectDifferencesAsync");
        var parameters = method.GetParameters();
        var log = Activator.CreateInstance(parameters[0].ParameterType,
            BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic, null,
            new object?[] { "repro", null, 2048 }, null)!;
        using var differences = (IDisposable)Activator.CreateInstance(parameters[3].ParameterType, nonPublic: true)!;
        var diagnostics = Activator.CreateInstance(parameters[4].ParameterType, nonPublic: true)!;
