            var items = ((IEnumerable<Diagnostic>)diagnostics).ToArray();
            Console.WriteLine($"EnC {label}: {items.Length} diagnostic(s): {string.Join(", ", items.Select(d => d.Id))}");
            if (items.Length != expected)
